//! The gear table: one pseudo-random 64-bit value per byte value, used by the rolling hash.
//!
//! The table is part of the repository format. Changing any value changes every chunk boundary,
//! which would destroy deduplication against existing snapshots. It is therefore generated by a
//! fixed, documented recipe instead of being a pasted list of numbers: entry `i` (0-based) is the
//! `(i + 1)`-th output of SplitMix64 started from state [`SEED`].

/// ASCII "VaultSna".
const SEED: u64 = 0x5661_756c_7453_6e61;
/// SplitMix64 state increment (the golden-ratio constant).
const INCREMENT: u64 = 0x9E37_79B9_7F4A_7C15;

/// The SplitMix64 output function applied to an already-incremented state.
const fn splitmix64_output(state: u64) -> u64 {
    let mut z = state;
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

const fn build() -> [u64; 256] {
    let mut table = [0_u64; 256];
    let mut state = SEED;
    let mut index = 0;
    while index < 256 {
        state = state.wrapping_add(INCREMENT);
        table[index] = splitmix64_output(state);
        index += 1;
    }
    table
}

/// Evaluated at compile time.
pub(super) static GEAR: [u64; 256] = build();

#[cfg(test)]
mod tests {
    use std::collections::HashSet;

    use super::*;

    #[test]
    fn splitmix64_matches_the_reference_implementation() {
        // First two outputs of Vigna's reference SplitMix64 seeded with 0.
        assert_eq!(splitmix64_output(INCREMENT), 0xE220_A839_7B1D_CDAF);
        assert_eq!(splitmix64_output(INCREMENT.wrapping_mul(2)), 0x6E78_9E6A_A1B9_65F4);
    }

    #[test]
    fn the_table_follows_the_documented_recipe() {
        assert_eq!(GEAR[0], splitmix64_output(SEED.wrapping_add(INCREMENT)));
        assert_eq!(GEAR[1], splitmix64_output(SEED.wrapping_add(INCREMENT.wrapping_mul(2))));
        assert_eq!(GEAR[255], splitmix64_output(SEED.wrapping_add(INCREMENT.wrapping_mul(256))));
    }

    #[test]
    fn entries_are_distinct_and_well_mixed() {
        let distinct: HashSet<u64> = GEAR.iter().copied().collect();
        assert_eq!(distinct.len(), 256);
        for (index, value) in GEAR.iter().enumerate() {
            let ones = value.count_ones();
            assert!((12..=52).contains(&ones), "entry {index} has {ones} set bits");
        }
    }
}
